const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get products table schema
const schema = db.prepare(\"PRAGMA table_info(products)\").all();
console.log('Products schema:', JSON.stringify(schema, null, 2));

// Query for PROD-FA0948
const product = db.prepare(\"SELECT * FROM products WHERE product_id = ?\").get('PROD-FA0948');
console.log('\nProduct PROD-FA0948:', JSON.stringify(product, null, 2));
"
